'use strict';
const $=id=>document.getElementById(id), E=WordLinks, dictionary=window.WORD_DICTIONARY;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{$('message').textContent='Storage is unavailable. Keep this page open to retain progress.'}}
function dateKey(){const d=new Date;return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
let today=dateKey(),dailyIndex=Math.floor(Date.UTC(...today.split('-').map((x,i)=>Number(x)-(i===1?1:0)))/86400000), index=dailyIndex,practice=false,words=[],selected=null,dir='h',won=false,step=0,helpReturn=null;
const bests=read('wl-bests',{}),history=read('wl-results',{});
const tutorials=[['Two words. A world of possibilities.','Two green starting words are waiting on a 15 × 15 board. Your challenge begins in the space between them.','BLOOM|STONE'],['Find a way to connect.','Build a continuous chain from one starting word to the other. You can grow your chain from either end.','ONE|TWO'],['Across or down. Your move.','Type a word, tap its starting square, then choose horizontal or vertical. The preview shows exactly where it will go.','→|↓'],['One crossing at a time.','Each new word crosses exactly one existing word at a matching letter. The final linking word crosses one word from each separate chain. Leave space beside words.','LINK'],['Every letter has a price.','Each word costs 10 base points plus 1 point per letter. DOG costs 13. HOUSE costs 15. Starting words are free.','10 + 5'],['The best route is the shortest.','Connect both starting words with the lowest total score. Replay to improve your personal best, or try a new practice puzzle.','Less is more.']];
function key(){return practice?`practice-${index%72}`:today}
function persist(){save('wl-progress',{today,index,practice,words:words.slice(2),won})}
function init(restore=false){const p=E.puzzle(index);words=p.seeds;won=false;selected=null;$('word').value='';if(restore){const old=read('wl-progress',null);if(old?.today===today&&Number.isInteger(old.index)&&typeof old.practice==='boolean'&&Array.isArray(old.words)){index=old.index;practice=old.practice;words=E.puzzle(index).seeds;for(const w of old.words){if(!w||typeof w.text!=='string')break;const result=E.validate(words,w,dictionary);if(!result.valid||won)break;words.push({text:w.text,r:w.r,c:w.c,dir:w.dir});won=result.winning}}}render();persist()}
function candidate(){return{text:$('word').value.trim().toUpperCase(),r:selected?.r,c:selected?.c,dir}}
function score(){return words.slice(2).reduce((n,w)=>n+10+w.text.length,0)}
function render(){const b=E.board(words),w=candidate(),result=selected&&w.text?E.validate(words,w,dictionary):null,preview=selected?E.cells(w):[],pmap=new Map(preview.filter(p=>p.r>=0&&p.r<15&&p.c>=0&&p.c<15).map(p=>[p.r*15+p.c,p]));$('grid').replaceChildren();for(let r=0;r<15;r++)for(let c=0;c<15;c++){const pos=r*15+c,existing=b.get(pos),p=pmap.get(pos),button=document.createElement('button');button.className='cell'+(existing?(existing.seed?' seed':' placed'):'')+(p?(result?.valid?' preview-valid':' preview-invalid'):'')+(selected?.r===r&&selected?.c===c?' selected':'');button.textContent=p?.letter||existing?.letter||'';button.setAttribute('role','gridcell');button.setAttribute('aria-label',`Row ${r+1}, column ${c+1}${existing?', '+existing.letter:''}${existing?.seed?', starting word':''}`);button.tabIndex=selected?(selected.r===r&&selected.c===c?0:-1):(r===0&&c===0?0:-1);button.onclick=()=>{selected={r,c};render()};button.onkeydown=e=>{const delta={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]}[e.key];if(delta){e.preventDefault();selected={r:Math.max(0,Math.min(14,r+delta[0])),c:Math.max(0,Math.min(14,c+delta[1]))};render();$('grid').children[selected.r*15+selected.c].focus()}};$('grid').append(button)}$('score').innerHTML=`${score()}<span>points</span>`;$('words').textContent=words.length-2;$('moves').textContent=words.length-2;$('best').textContent=bests[key()]??'—';$('horizontal').setAttribute('aria-pressed',dir==='h');$('vertical').setAttribute('aria-pressed',dir==='v');$('selection').textContent=selected?`Starts at row ${selected.r+1}, column ${selected.c+1} · ${dir==='h'?'across':'down'}`:'Select a starting square on the board.';$('message').textContent=won?'Connected! Replay to find a more efficient route.':result?.reason||(w.text?'Select the first square of your word.':'Choose a square, then build your next link.');$('message').className=result&&!result.valid?'error':'';$('place').disabled=won||!result?.valid;$('place').innerHTML=result?.valid?`Place word <span>+${result.cost} points</span>`:'Place word <span>↗</span>';$('daily-return').hidden=!practice;$('puzzle-label').textContent=practice?'Practice Word Links':"Today's Word Links";$('puzzle-number').textContent=`NO. ${String(index%72+1).padStart(3,'0')}`;$('date').textContent=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase()}
function place(){if(won)return{ok:false,reason:'Puzzle is complete.'};const w=candidate(),result=E.validate(words,w,dictionary);if(!result.valid)return{ok:false,reason:result.reason};words.push(w);won=result.winning;selected=null;$('word').value='';if(won){bests[key()]=Math.min(bests[key()]??Infinity,score());save('wl-bests',bests);if(!practice){history[today]={score:score(),words:words.length-2};save('wl-results',history)}}persist();render();if(won)victory();else $('word').focus();return{ok:true,score:score(),complete:won}}
function victory(){$('performance').textContent=score()<=45?'Excellent link. Every letter earned its place.':score()<=65?'Beautifully connected. Can you find a shorter route?':'Connection made. A fresh route could cost you less.';$('final-score').textContent=score()+' points';$('final-stats').textContent=`${words.length-2} words · ${words.length-2} moves · Best: ${bests[key()]} points`;$('share-status').textContent='';$('victory').showModal()}
function reset(newPuzzle){if(words.length>2&&!won&&!confirm('Start over? Your current unfinished links will be cleared.'))return;if($('victory').open)$('victory').close();if(newPuzzle){index++;practice=true}init()}
function showTutorial(){helpReturn=document.activeElement;step=0;drawTutorial();$('tutorial').showModal()}
function drawTutorial(){const t=tutorials[step];$('step-label').textContent=`HOW TO PLAY · ${step+1} OF 6`;$('step-title').textContent=t[0];$('step-copy').textContent=t[1];$('back').disabled=step===0;$('next').textContent=step===5?'Play Word Links':'Next →';$('dots').innerHTML=tutorials.map((_,i)=>`<i class="${i===step?'active':''}"></i>`).join('');$('tutorial-art').innerHTML=step===0||step===1?t[2].split('|').map(x=>`<div>${[...x].map(l=>`<span class="tile">${l}</span>`).join('')}</div>`).join('<span class="connector">⋯</span>'):step===3?[...'LINK'].map(l=>`<span class="tile">${l}</span>`).join(''):`<span class="points">${t[2].replace('|',' &nbsp; ')}</span>`;if(step===0){$('tutorial-art').style.flexDirection='column'}else $('tutorial-art').style.flexDirection='row'}
$('next').onclick=()=>{if(step<5){step++;drawTutorial()}else{$('tutorial').close();save('wl-tutorial',true);$('word').focus()}};$('back').onclick=()=>{if(step){step--;drawTutorial()}};$('help').onclick=showTutorial;$('close-help').onclick=()=>{$('tutorial').close();helpReturn?.focus()};$('word').oninput=render;$('word').onkeydown=e=>{if(e.key==='Enter'&&!$('place').disabled)place()};$('horizontal').onclick=()=>{dir='h';render()};$('vertical').onclick=()=>{dir='v';render()};$('place').onclick=place;$('replay').onclick=()=>reset(false);$('new').onclick=()=>reset(true);$('win-replay').onclick=()=>reset(false);$('win-new').onclick=()=>reset(true);$('view-board').onclick=()=>$('victory').close();$('share').onclick=async()=>{const text=`Bostonian Times Word Links\n${practice?'Practice puzzle '+(index%72+1):today}\nScore: ${score()}\nWords: ${words.length-2}\nMoves: ${words.length-2}\n🟩${'▫️'.repeat(Math.min(words.length-2,10))}🟩`;try{await navigator.clipboard.writeText(text);$('share-status').textContent='Result copied. Your words stay a secret.'}catch{$('share-status').textContent='Copy your result below:';const area=document.createElement('textarea');area.value=text;area.style.width='100%';$('share-status').append(area);area.select()}};
$('daily-return').onclick=()=>{if(words.length>2&&!won&&!confirm('Return to today’s puzzle and clear these practice links?'))return;index=dailyIndex;practice=false;init()};
init(true);if(!read('wl-tutorial',false))showTutorial();
window.addEventListener('focus',()=>{if(dateKey()!==today){today=dateKey();dailyIndex=Math.floor(Date.UTC(...today.split('-').map((x,i)=>Number(x)-(i===1?1:0)))/86400000);index=dailyIndex;practice=false;if($('victory').open)$('victory').close();init()}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_word_links_board',description:'Read the current Word Links puzzle, placed words and score.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({words:words.map(w=>({...w})),score:score(),complete:won})})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'place_word_link',description:'Place a word on the current board using zero-based row and column. Invalid placements leave the board unchanged.',inputSchema:{type:'object',properties:{word:{type:'string'},row:{type:'integer',minimum:0,maximum:14},column:{type:'integer',minimum:0,maximum:14},direction:{type:'string',enum:['h','v']}},required:['word','row','column','direction'],additionalProperties:false},execute:input=>{if(typeof input.word!=='string'||!Number.isInteger(input.row)||!Number.isInteger(input.column)||!['h','v'].includes(input.direction))return{ok:false,reason:'Invalid word placement input.'};const proposed={text:input.word.toUpperCase(),r:input.row,c:input.column,dir:input.direction};const result=E.validate(words,proposed,dictionary);if(!result.valid||won)return{ok:false,reason:won?'Puzzle is complete.':result.reason};selected={r:input.row,c:input.column};dir=input.direction;$('word').value=proposed.text;return place()}})).catch(()=>{})}catch{}}
